\fill (P) circle (2.5pt);
\fill (Q) circle (2.5pt);
\fill (R) circle (2.5pt);
\fill (S) circle (2.5pt);
\node[below left] at (P) {$P$};
\node[below right] at (Q) {$Q$};
\node[above left] at (R) {$R$};
\node[above left] at (S) {$S$};
